import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"LINE","description":"","frontmatter":{},"headers":[],"relativePath":"channels/line.md","filePath":"channels/line.md"}'),i={name:"channels/line.md"};function o(r,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="line" tabindex="-1">LINE <a class="header-anchor" href="#line" aria-label="Permalink to &quot;LINE&quot;">​</a></h1><p>LINE connects a Messaging API channel for a LINE Official Account to the gateway through a signed HTTPS webhook. It supports private chats, groups and rooms.</p><h2 id="create-the-account-and-credentials" tabindex="-1">Create the account and credentials <a class="header-anchor" href="#create-the-account-and-credentials" aria-label="Permalink to &quot;Create the account and credentials&quot;">​</a></h2><p>You need a LINE Business ID, an Official Account you administer, an existing gateway agent, and a public HTTPS webhook URL.</p><ol><li>Create a LINE Official Account, or open an existing one in <strong>LINE Official Account Manager</strong>.</li><li>Enable <strong>Messaging API</strong> and choose its provider. This creates the Messaging API channel; new Messaging API channels are no longer created directly in the Developers Console. Follow <a href="https://developers.line.biz/en/docs/messaging-api/getting-started/" target="_blank" rel="noreferrer">LINE&#39;s account setup guide</a>.</li><li>Open that channel in the <a href="https://developers.line.biz/console/" target="_blank" rel="noreferrer">LINE Developers Console</a>. Copy its <strong>Channel secret</strong> from Basic settings.</li><li>Issue a <strong>Channel access token</strong>. A long-lived token can be issued from the Messaging API tab; LINE also supports token types with expiration; see <a href="https://developers.line.biz/en/docs/basics/channel-access-token/" target="_blank" rel="noreferrer">channel access tokens</a>. The gateway accepts the issued token string, but does not issue or rotate it for you.</li></ol><p>The secret verifies incoming messages; the access token sends replies and downloads attachments. A Channel ID cannot replace either credential. See <a href="https://developers.line.biz/en/docs/messaging-api/building-bot/" target="_blank" rel="noreferrer">LINE&#39;s bot configuration guide</a>.</p><h2 id="configure-the-gateway-and-webhook" tabindex="-1">Configure the gateway and webhook <a class="header-anchor" href="#configure-the-gateway-and-webhook" aria-label="Permalink to &quot;Configure the gateway and webhook&quot;">​</a></h2><p>Run <code>claude-gateway agents update --agent assistant</code>, select LINE, and supply both credentials. Alternatively, add this fragment to the existing agent configuration and restart with its referenced environment variables available:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;line&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;channelAccessToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${LINE_CHANNEL_ACCESS_TOKEN}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;channelSecret&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${LINE_CHANNEL_SECRET}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dmPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dmAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;groupPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;groupAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;requireMention&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;pairing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The equivalent credential fields for <code>PATCH /api/v1/agents/:agentId</code> are <code>line_channel_access_token</code> and <code>line_channel_secret</code>.</p><p>In the channel&#39;s Messaging API settings, set the webhook URL to your gateway&#39;s public route, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://gateway.example.com/gateway/webhooks/line/assistant</span></span></code></pre></div><p>Use the path your proxy actually publishes; a direct gateway host may omit <code>/gateway</code>. Click <strong>Verify</strong>, then enable <strong>Use webhook</strong>. Disable the Official Account&#39;s automatic reply/greeting messages while testing if they obscure the gateway&#39;s reply. LINE requires HTTPS with a trusted certificate. These settings are described in <a href="https://developers.line.biz/en/docs/messaging-api/building-bot/#set-webhook-url" target="_blank" rel="noreferrer">LINE&#39;s webhook setup instructions</a>.</p><p>Preserve the exact request body and <code>x-line-signature</code> header through your proxy. On the bundled tunnel deployment, use the gateway&#39;s Bun proxy path rather than bypassing it. A verification success is only a reachability check; test a real signed message next.</p><h2 id="approve-a-sender-and-a-group" tabindex="-1">Approve a sender and a group <a class="header-anchor" href="#approve-a-sender-and-a-group" aria-label="Permalink to &quot;Approve a sender and a group&quot;">​</a></h2><p>Add the Official Account as a friend using its QR code and send a private text message. Under the default allowlist policy, the sender receives a one-time pairing code. Open the agent&#39;s LINE settings, compare the pending code with the sender, and add their <code>U...</code> user ID to <code>dmAllowlist</code>. Send another message to verify a reply.</p><p>For API administration, read <code>GET /api/v1/agents/assistant/line/pending</code> with an admin key, then update <code>line_dm_allowlist</code> through the agent PATCH API. These arrays replace the existing list, so include existing approved IDs. The CLI <code>channels approve</code> command is for Telegram/Discord only.</p><p>For groups, enable the channel&#39;s permission to join group chats in the LINE console, invite the bot, then approve the discovered <code>C...</code> group ID or <code>R...</code> room ID in <code>groupAllowlist</code>. The API fields are <code>line_group_policy</code>, <code>line_group_allowlist</code>, <code>line_require_mention</code> and <code>line_pairing</code>. Use actual IDs from discovery, never names.</p><p>With <code>requireMention: true</code>, only a <strong>native LINE mention</strong> of the bot passes. Typing its name or <code>@All</code> does not count. Mentions belong to text events: an image, document or audio message in a group cannot satisfy this gate. Use DMs for these attachments or deliberately set <code>requireMention: false</code> for allowed groups.</p><h2 id="messages-voice-and-commands" tabindex="-1">Messages, voice and commands <a class="header-anchor" href="#messages-voice-and-commands" aria-label="Permalink to &quot;Messages, voice and commands&quot;">​</a></h2><p>Text, images and files are accepted; attachment downloads have a 20 MB cap. Unsupported or unavailable files are identified to the agent rather than presented as a successful download. Stickers, video and location messages are ignored.</p><p>With <code>gateway.orchestration: true</code> and the agent&#39;s <a href="/claude-gateway/guide/voice.html">voice configuration</a>, LINE audio messages can be transcribed. Spoken replies use AAC-LC M4A audio with a scoped HTTPS share URL that expires after 30 minutes; configure a reachable public gateway URL for LINE to fetch that audio. Install <code>ffmpeg</code> in the gateway environment for LINE audio conversion. The account&#39;s access and group mention gates still apply before audio reaches the agent.</p><p>Orchestration chat controls include <code>/session</code>, <code>/sessions</code>, <code>/tasks</code>, <code>/stop</code>, <code>/voice</code> and <code>/voices</code>, with LINE postback controls. <code>/voice on</code>, <code>/voice auto</code> and <code>/voice off</code> select Always, voice-input-only and Off. Voice is disabled for new agents, and each chat&#39;s automatic voice replies start Off. Configure <code>agents[].voice</code> before enabling them. In private chat, <code>/model &lt;id or alias&gt;</code> selects a model from the available catalog and affects the whole agent.</p><p>Replies use a LINE reply token first, with push-message fallback when needed. A single-use reply token has a short lifetime, so slow answers may consume the account&#39;s push quota. Optional <code>line.slowResponseThreshold</code> defaults to 45 seconds: the gateway can send a <strong>Get answer</strong> button, whose tap provides a fresh reply token. Set it to <code>0</code> to disable this behavior; <code>slowButtonLabel</code> and <code>slowPendingText</code> customize its text. Requests are chunked to LINE&#39;s five-message-object limit.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Webhook <code>404</code></td><td>Agent ID and configured <code>channelSecret</code>; public path prefix</td></tr><tr><td>Webhook <code>401</code></td><td>Correct channel secret and unmodified raw body/signature</td></tr><tr><td>Verify succeeds but no answer</td><td>Use webhook enabled, a supported real message sent, pending sender approved</td></tr><tr><td>Duplicate canned replies</td><td>Official Account auto-replies and greeting settings</td></tr><tr><td>Group text ignored</td><td>Bot membership, group allowlist and native mention</td></tr><tr><td>Group attachment ignored</td><td>Attachment cannot carry the native mention required by the default policy</td></tr><tr><td>Slow reply fails</td><td>Reply token expiry, push quota, Get answer button configuration</td></tr><tr><td>Audio ignored</td><td>Gateway orchestration, agent voice/notes settings, <code>ffmpeg</code>, access/mention policy</td></tr></tbody></table><p>Implementation references: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/line-webhook-router.ts" target="_blank" rel="noreferrer">LINE webhook</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/line-mention.ts" target="_blank" rel="noreferrer">mention gate</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/agent/line-reply-manager.ts" target="_blank" rel="noreferrer">reply-token handling</a>.</p>`,27)])])}const u=a(i,[["render",o]]);export{g as __pageData,u as default};
